#!/bin/sh
# SPDX-License-Identifier: GPL-2.0
# tools/build-final-module.sh - rebuild the FINAL association module with this
# lane's EAPOL/data RX free-ring refill watermark (lane wifi-rx-watermark,
# shared task task-156).  HOST-ONLY: builds a module, never touches the bench.
#
# Chain (all committed, no vendor binaries):
#   1. final association tree 251d08f0 (assoc-stripped sha), regenerated by
#      ../wifi-stability/tools/build-association-module.sh
#   2. ../wifi-sibling-gpl/patches/0001-mgmt-tx-hcc-g0id6-carrier.patch
#      (the corrected HCC g0 id6 management-TX carrier, ab9e18a4 artifact)
#   3. patches/0001-rx-refill-watermark.patch (this lane: rx_refill_wm)
#
#   ./tools/build-final-module.sh
#   ASSOC_TREE=/tmp/wifi-assoc-build/integ ./tools/build-final-module.sh
#   REBUILD_ASSOC=1 ./tools/build-final-module.sh   # regenerate step 1 first
#
# Artifact (never committed): ${ART:-/tmp/wifi-rx-watermark-artifact}/
#   hi5622_wifi.stripped.ko   <- bake/fire this file
#   hi5622_wifi.ko.unstripped
#   build.log, params.txt
#
# Reproducibility note: the sha256 of a Linux module changes with the build
# directory through the 20-byte GNU build-id (ld hashes the pre-strip DWARF,
# whose comp_dir is the absolute path), while code/params are identical.  Quote
# the sha of the exact file that is baked; compare rebuilds by .text + params.
set -eu
LANE_DIR=$(cd "$(dirname "$0")/.." && pwd)
DOCS=$(cd "$LANE_DIR/.." && pwd)
ASSOC_TREE=${ASSOC_TREE:-/tmp/wifi-assoc-build/integ}
WORK=${WORK:-/tmp/wifi-rx-watermark-build/rebuild}
ART=${ART:-/tmp/wifi-rx-watermark-artifact}
ARTWORK=$ART.work
MGMT_PATCH=$DOCS/wifi-sibling-gpl/patches/0001-mgmt-tx-hcc-g0id6-carrier.patch
WM_PATCH=$LANE_DIR/patches/0001-rx-refill-watermark.patch

if [ "${REBUILD_ASSOC:-0}" = "1" ] || [ ! -d "$ASSOC_TREE" ]; then
	echo "== 0. regenerate the final association tree (../wifi-stability/tools/build-association-module.sh)"
	( cd "$DOCS/wifi-stability" && ./tools/build-association-module.sh )
	ASSOC_TREE=/tmp/wifi-assoc-build/integ
fi
[ -d "$ASSOC_TREE" ] || { echo "final: association tree missing: $ASSOC_TREE" >&2; exit 2; }
[ -f "$MGMT_PATCH" ] || { echo "final: missing mgmt carrier patch: $MGMT_PATCH" >&2; exit 2; }
[ -f "$WM_PATCH" ] || { echo "final: missing watermark patch: $WM_PATCH" >&2; exit 2; }

KDIR=
STAGING_DIR=
set +u
[ -n "${KDIR_OVERRIDE:-}" ] && KDIR=$KDIR_OVERRIDE
[ -n "${STAGING_OVERRIDE:-}" ] && STAGING_DIR=$STAGING_OVERRIDE
set -u
if [ -z "$KDIR" ]; then
	for root in /home/shibbityshwab/openwrt-lab-upstream-target \
		    /home/shibbityshwab/openwrt-lab-selectorfix-img; do
		c=$root/build_dir/target-arm_cortex-a9_musl_eabi/linux-hisilicon_luofu/linux-6.18.60
		if [ -d "$c" ]; then KDIR=$c; STAGING_DIR=$root/staging_dir; break; fi
	done
fi
[ -d "$KDIR" ] || { echo "final: 6.18.60 kernel tree not found" >&2; exit 2; }
[ -n "$STAGING_DIR" ] || { echo "final: staging dir not found" >&2; exit 2; }
CROSS=$STAGING_DIR/toolchain-arm_cortex-a9_gcc-14.4.0_musl_eabi/bin/arm-openwrt-linux-muslgnueabi-
[ -x "${CROSS}gcc" ] || { echo "final: cross gcc missing" >&2; exit 2; }
export STAGING_DIR

echo "== 1. stage the final association tree"
rm -rf "$WORK"
mkdir -p "$WORK"
cp -a "$ASSOC_TREE/." "$WORK/"
( cd "$WORK" && rm -f *.o *.ko *.mod *.mod.c .*.cmd Module.symvers modules.order .modules.order.cmd .module-common.o module-common.o .t1 .t2 2>/dev/null ) || true
echo "   $(ls "$WORK" | wc -l) staged files"

echo "== 2. apply the corrected mgmt-TX carrier patch (wifi-sibling-gpl)"
( cd "$WORK" && patch -p1 --dry-run < "$MGMT_PATCH" >/dev/null && patch -p1 --no-backup-if-mismatch < "$MGMT_PATCH" >/dev/null )

echo "== 3. apply the RX refill watermark patch (this lane)"
( cd "$WORK" && patch -p1 --dry-run < "$WM_PATCH" >/dev/null && patch -p1 --no-backup-if-mismatch < "$WM_PATCH" >/dev/null )
if grep -rln '^<<<<<<<' "$WORK" >/dev/null 2>&1; then
	echo "final: conflict markers survived - refusing build" >&2
	exit 1
fi

echo "== 4. build against $KDIR"
make ARCH=arm CROSS_COMPILE="$CROSS" -C "$KDIR" M="$WORK" modules > "$WORK/build.log" 2>&1 || {
	echo "final: BUILD FAILED" >&2
	tail -40 "$WORK/build.log" >&2
	exit 1
}
if grep -iE 'warning:|error:|undefined!' "$WORK/build.log"; then
	echo "final: warnings/errors/undefined symbols - refusing artifact" >&2
	exit 1
fi
KO=$WORK/hi5622_wifi.ko
[ -f "$KO" ] || { echo "final: no .ko" >&2; exit 1; }

echo "== 5. strip and verify"
rm -rf "$ARTWORK"
mkdir -p "$ARTWORK"
"$CROSS"strip --strip-debug -o "$ARTWORK/hi5622_wifi.stripped.ko" "$KO"
"$CROSS"objcopy -O binary --only-section=.text "$KO" "$WORK/.t1"
"$CROSS"objcopy -O binary --only-section=.text "$ARTWORK/hi5622_wifi.stripped.ko" "$WORK/.t2"
cmp -s "$WORK/.t1" "$WORK/.t2" || { echo "final: strip changed .text" >&2; exit 1; }
cp "$KO" "$ARTWORK/hi5622_wifi.ko.unstripped"
cp "$WORK/build.log" "$ARTWORK/build.log"
modinfo -p "$ARTWORK/hi5622_wifi.stripped.ko" > "$ARTWORK/params.txt"

NP=$(wc -l < "$ARTWORK/params.txt")
[ "$NP" = "57" ] || { echo "final: param count $NP != 57" >&2; exit 1; }
missing=""
for p in rx_refill_wm rx_enable rx_clear_status rx_drain_max mgmt_tx mgmt_rx \
	 sta_ops eapol_rx data_tx data_tx_peer wpa_keys beacon_static vap_start_first; do
	grep -q "^${p}:" "$ARTWORK/params.txt" || missing="$missing $p"
done
[ -z "$missing" ] || { echo "final: missing params:$missing" >&2; exit 1; }

SV=$WORK/cfg80211-provider.symvers
[ "$(wc -l < "$SV")" = "12" ] || { echo "final: cfg80211 symvers != 12 lines" >&2; exit 1; }
for sym in cfg80211_bss_iter cfg80211_mgmt_tx_status_ext cfg80211_rx_mgmt_ext; do
	grep -q "$sym" "$SV" || { echo "final: $sym missing from symvers" >&2; exit 1; }
	"$CROSS"nm -u "$ARTWORK/hi5622_wifi.stripped.ko" | grep -q " ${sym}\$" || {
		echo "final: $sym not imported by the .ko" >&2; exit 1; }
done
for s in "rx_refill_wm" "RX watermark:" "watermark refill" \
	 "DP rx_arm" "set_default_mgmt_key posted" "data-tx tx: posts="; do
	strings -a "$ARTWORK/hi5622_wifi.stripped.ko" | grep -qF "$s" || {
		echo "final: feature string missing: $s" >&2; exit 1; }
done
# corrected mgmt-TX carrier (sibling-gpl task-151) + its g1 id13 RX decoder
for sym in himg_build_hcc_mgmt_tx himg_parse_rx_mgmt; do
	"$CROSS"nm "$ARTWORK/hi5622_wifi.stripped.ko" | grep -q " ${sym}\$" || {
		echo "final: $sym missing from the .ko" >&2; exit 1; }
done
VERMAGIC=$("$CROSS"strings "$KO" | grep -m1 '^vermagic=')
[ -n "$VERMAGIC" ] || { echo "final: no vermagic" >&2; exit 1; }

rm -rf "$ART"
mv "$ARTWORK" "$ART"

echo
echo "== FINAL ASSOCIATION + RX WATERMARK module (host-built, NOT fired)"
echo "artifact  : $ART/hi5622_wifi.stripped.ko"
echo "size      : $(stat -c %s "$ART/hi5622_wifi.stripped.ko")"
echo "sha256    : $(sha256sum "$ART/hi5622_wifi.stripped.ko" | cut -d' ' -f1)"
echo "unstripped: $(stat -c %s "$ART/hi5622_wifi.ko.unstripped") B sha256 $(sha256sum "$ART/hi5622_wifi.ko.unstripped" | cut -d' ' -f1)"
echo "params    : $NP (56 + rx_refill_wm)"
echo "$VERMAGIC"
echo "chain     : assoc 251d08f0 + mgmt carrier ab9e18a4 + rx-refill-watermark 5c94d076"
echo "fire      : see TEST-LADDER.md; fail-closed default = rx_enable=0, watermark inert"
